rename table `email_templates` to `notification_templates`;
alter table `notification_templates` add `mail_enabled` enum('force', 'choice_on', 'choice_off', 'never') not null default 'choice_on' after `enabled`;
alter table `notification_templates` add `in_app_enabled` enum('force', 'choice_on', 'choice_off', 'never') not null default 'choice_on' after `mail_enabled`;
alter table `notification_templates` add `in_app_title` varchar(255) null after `subject`;
alter table `notification_templates` add `in_app_body` text null after `body`;
alter table `notification_templates` add `in_app_url` varchar(255) null after `in_app_body`;
alter table `notification_templates` add `edit_preference_message` varchar(255) null after `in_app_body`;
update `notification_templates` set `in_app_title` = 'New login detected', `in_app_body` = 'A new login was detected on your account from IP: {{ $ip }} using {{ $device }} at {{ $time }}.', `mail_enabled` = 'force', `in_app_enabled` = 'choice_off', `edit_preference_message` = 'Alert me about new login attempts', `in_app_url` = '{{ route(\"profile.security\") }}' where `key` = 'new_login_detected';
update `notification_templates` set `in_app_title` = 'New invoice created', `in_app_body` = 'A new invoice was created on your account with total amount: {{ $total }}.', `mail_enabled` = 'choice_on', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Notify me about new invoices', `in_app_url` = '{{ route(\"invoices.show\", $invoice) }}' where `key` = 'new_invoice_created';
update `notification_templates` set `in_app_title` = 'Invoice paid', `in_app_body` = 'Your invoice #{{ $invoice->id }} has been successfully paid with total amount: {{ $invoice->formattedTotal }}.', `mail_enabled` = 'choice_on', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Notify me about successful payments', `in_app_url` = '{{ route(\"invoices.show\", $invoice) }}' where `key` = 'invoice_paid';
update `notification_templates` set `in_app_title` = 'Invoice payment failed', `in_app_body` = 'Your invoice #{{ $invoice->id }} payment has failed. Please pay the invoice to avoid service interruptions.', `mail_enabled` = 'choice_on', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Alert me about payment failures', `in_app_url` = '{{ route(\"invoices.show\", $invoice) }}' where `key` = 'invoice_payment_failed';
update `notification_templates` set `in_app_title` = 'New order created', `in_app_body` = 'A new order was created on your account.', `mail_enabled` = 'choice_on', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Send me order confirmations', `in_app_url` = '{{ route(\"services\") }}' where `key` = 'new_order_created';
update `notification_templates` set `in_app_title` = 'Service activated', `in_app_body` = 'Your service {{ $service->product->name }} has been activated.', `mail_enabled` = 'force', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Notify me about new service activations', `in_app_url` = '{{ route(\"services.show\", $service) }}' where `key` = 'new_server_created';
update `notification_templates` set `in_app_title` = 'Service suspended', `in_app_body` = 'Your service {{ $service->product->name }} has been suspended due to a payment failure. Please pay the invoice to reactivate the service.', `mail_enabled` = 'force', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Alert me about service suspensions', `in_app_url` = '{{ route(\"services.show\", $service) }}' where `key` = 'server_suspended';
update `notification_templates` set `in_app_title` = 'Server terminated', `in_app_body` = 'Your server {{ $service->product->name }} has been terminated.', `mail_enabled` = 'force', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Alert me about service terminations', `in_app_url` = '{{ route(\"services.show\", $service) }}' where `key` = 'server_terminated';
update `notification_templates` set `in_app_title` = 'New ticket reply', `in_app_body` = 'You have a new reply on your ticket #{{ $ticketMessage->ticket_id }}.', `mail_enabled` = 'choice_on', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Notify me about ticket replies', `in_app_url` = '{{ route(\"tickets.show\", $ticketMessage->ticket_id) }}' where `key` = 'new_ticket_message';
update `notification_templates` set `in_app_title` = 'Service cancellation received', `in_app_body` = 'Your server cancellation has been successfully received.', `mail_enabled` = 'choice_on', `in_app_enabled` = 'choice_on', `edit_preference_message` = 'Notify me about service cancellations', `in_app_url` = '{{ route(\"services.show\", $service) }}' where `key` = 'service_cancellation_received';
